# Compact the record-r1 JSONL for the report. Does not change the JSONL.
# Do not edit this file after it has run.
import json
from collections import Counter
from pathlib import Path

rows = [json.loads(line) for line in Path('work/out/record-r1.jsonl').read_text(encoding='utf-8').splitlines() if line]
out = []
def w(s=''):
    out.append(s)

for row in rows:
    step = row.get('step')
    if not step.endswith('-s1') or 'producerGets' not in row:
        if step == 'done':
            w('done ok=%s reasons=%s' % (row.get('ok'), row.get('reasons')))
        continue
    w('== ' + step)
    pose = row['pose']
    w('pose raw %s index %s exif %s completion-in-read %s' % (pose['raw'], pose['index'], pose['exif'], pose.get('enable')))
    w('move %s' % json.dumps(row['move']))
    w('entryDelta %s' % json.dumps(row['entryDelta']))
    w('entries %s' % json.dumps(row['producerEntries']))
    for label in ('before', 'held', 'released'):
        rec = row[label]['records']
        w('%s capture %s consumer %s dirty %s' % (label, rec['capture'], rec['consumer'], rec['dirty']))
    def pack(items, keys):
        c = Counter((it['key'], it['index'], it['caller']) for it in items if it['key'] in keys)
        return ' '.join('%04x:%d@%08x x%d' % (k, i, caller, n) for (k, i, caller), n in sorted(c.items()))
    watch = {0x99a1, 0x5962, 0x9a41, 0x1dd1, 0x88b2, 0x84d1, 0x1df1, 0x1e01}
    w('editor ' + pack(row['editorGets'], watch))
    w('producer ' + pack(row['producerGets'], watch))
    w('editorSets %d producerSets %d' % (len(row['editorSets']), len(row['producerSets'])))
    if row['producerSets']:
        w('producerSets ' + pack(row['producerSets'], watch | {0x99a1, 0x5962, 0x84d1, 0x88b2}))
    # unique producer callers
    callers = sorted({it['caller'] for it in row['producerGets']})
    w('producer callers %s' % ' '.join('%08x' % c for c in callers))

text = '\n'.join(out) + '\n'
Path('work/out/record-r1-summary.txt').write_text(text, encoding='utf-8')
print(text)
